// desktop/src/app-icons.mjs — which desktop/assets file is the window icon and the tray image (docs/desktop.md
// "Window and icons"). The files are generated by tools/desktop-icons.mjs. Pure: no imports.

/** macOS takes the Dock icon from the bundle's .icns; Windows and Linux get a 256px window icon. */
export function windowIconFile(platform) {
  return platform === 'darwin' ? null : 'icon.png';
}

/** macOS: a template image (the menu bar tints it). Elsewhere a white mark on a dark taskbar, a black one on a light one. */
export function trayImageFile({ platform, darkSystemUI }) {
  if (platform === 'darwin') return 'trayTemplate.png';
  return darkSystemUI ? 'tray-white.png' : 'tray-black.png';
}

/** The taskbar / menu bar theme: shouldUseDarkColorsForSystemIntegratedUI (Windows, macOS), else shouldUseDarkColors. */
export function systemUIDark(nativeTheme) {
  const t = nativeTheme || {};
  if (typeof t.shouldUseDarkColorsForSystemIntegratedUI === 'boolean') return t.shouldUseDarkColorsForSystemIntegratedUI;
  return !!t.shouldUseDarkColors;
}
